


import base64
from PIL import Image
from io import BytesIO

# 你的Base64字符串 (以你提供的 /9j/ 开头)
base64_string = ""

# 1. 解码Base64字符串为二进制数据
image_data = base64.b64decode(base64_string)

# 2. 将二进制数据转换为字节流，并用PIL打开为图像对象
image = Image.open(BytesIO(image_data))

# 3. 显示图片 (会弹出默认图片查看器)
image.show()

# 你也可以对图片进行其他操作，例如：
# image.save("output.jpg")  # 保存到文件
# print(image.size, image.mode)  # 打印图片尺寸和模式